/* -*- mode: C; c-file-style: "gnu"; indent-tabs-mode: nil; -*- */
/*
 * permission-store.c: Proxy for the org.freedesktop.impl.portal.PermissionStore
 * D-Bus interface. Port of js/misc/permissionStore.js.
 *
 * The proxy is the one generated by gdbus-codegen from
 * data/dbus-interfaces/org.freedesktop.impl.portal.PermissionStore.xml:
 * D-Bus methods are shell_portal_permission_store_call_*() functions, the Changed
 * signal is the #ShellPortalPermissionStore::changed GObject signal. Like the proxy
 * the JS built, it is created with %G_DBUS_PROXY_FLAGS_NONE, so the name is
 * activated on creation and #GDBusProxy:g-name-owner is %NULL if that fails
 * (for instance because xdg-desktop-portal is not installed).
 *
 * SPDX-License-Identifier: GPL-2.0-or-later
 */

#include "config.h"

#include "misc/permission-store.h"

#define PERMISSION_STORE_BUS_NAME "org.freedesktop.impl.portal.PermissionStore"
#define PERMISSION_STORE_PATH "/org/freedesktop/impl/portal/PermissionStore"

/**
 * shell_permission_store_new:
 * @cancellable: (nullable): a #GCancellable
 * @callback: (scope async): called when the proxy is ready
 * @user_data: (closure): user data for @callback
 *
 * Starts creating a proxy for org.freedesktop.impl.portal.PermissionStore on
 * the session bus. Finish with shell_permission_store_new_finish().
 */
void
shell_permission_store_new (GCancellable        *cancellable,
                            GAsyncReadyCallback  callback,
                            gpointer             user_data)
{
  shell_portal_permission_store_proxy_new_for_bus (G_BUS_TYPE_SESSION,
                                            G_DBUS_PROXY_FLAGS_NONE,
                                            PERMISSION_STORE_BUS_NAME,
                                            PERMISSION_STORE_PATH,
                                            cancellable,
                                            callback,
                                            user_data);
}

/**
 * shell_permission_store_new_finish:
 * @res: a #GAsyncResult
 * @error: return location for a #GError
 *
 * Returns: (transfer full): the permission store proxy, or %NULL with @error set
 */
ShellPortalPermissionStore *
shell_permission_store_new_finish (GAsyncResult  *res,
                                   GError       **error)
{
  return shell_portal_permission_store_proxy_new_for_bus_finish (res, error);
}
